  id: "size-swap",
  classes: ["lateral-host"],
  title: { en: "Directional size swap", zh: "方向切换与尺寸跟随" },
  description: {
    en: "A local panel follows a directional content swap; leaving content is lifted out of flow.",
    zh: "局部面板跟随内容切换改变高度，离场内容先脱离布局。",
  },
